private void isInvulnerable_SpellEngine(DamageSource damageSource, CallbackInfoReturnable<Boolean> cir) {
    // Check if the player has a protection effect
    if (Protection.tryProtect((PlayerEntity) (Object) this, damageSource)) {
        cir.setReturnValue(true);
        cir.cancel();
    }
}

public static boolean tryProtect(LivingEntity entity, DamageSource damageSource) {
    for (var entry: entity.getActiveStatusEffects().entrySet()) {
        var optionalKey = entry.getKey().getKey();
        if (optionalKey.isEmpty()) { // Should never happen, added due to some incompatibility crash
            continue;
        }
        var key = optionalKey.get();
        var protection = PROTECTIONS.get(key);
        if (protection != null) {
            if (protection.protects != null && !damageSource.isIn(protection.protects)) {
                continue; // This protection does not apply to this damage type
            }
            var effect = entry.getValue();
            var newAmplifier = effect.getAmplifier() - protection.decrement;

            var pop = newAmplifier < 0 ? protection.onRemove : protection.onDecrement;
            if (pop != null) {
                ParticleHelper.sendBatches(entity, pop.particles);
                if (pop.sound != null) {
                    SoundHelper.playSoundEvent(entity.getWorld(), entity, pop.sound);
                }
            }
            StatusEffectUtil.applyChanges(entity, List.of(
                    new StatusEffectUtil.Diff(effect, newAmplifier)
            ));
            return true;
        }
    }
    return false;
}

public static void applyChanges(LivingEntity livingEntity, List<Diff> changes) {
    for (var change : changes) {
        final var newAmplifier = change.newAmplifier;
        if (change.delay > 0) {
            final var effectType = change.effect.getEffectType();
            ((WorldScheduler)livingEntity.getWorld()).schedule(change.delay - 1, () -> {
                var effect = livingEntity.getStatusEffect(effectType);
                if (effect == null) {
                    // If the effect is not present, we can skip processing
                    return;
                }
                processRemoval(livingEntity, effect, newAmplifier);
            });
        } else {
            processRemoval(livingEntity, change.effect, newAmplifier);
        }
    }
}

private static void processRemoval(LivingEntity livingEntity, StatusEffectInstance effect, int newAmplifier) {
    if (newAmplifier < 0) {
        livingEntity.removeStatusEffect(effect.getEffectType());
    } else {
        var current = effect;
        var newInstance = copyWithNewAmplifier(current, newAmplifier);
        livingEntity.removeStatusEffect(effect.getEffectType());
        livingEntity.addStatusEffect(newInstance);
    }
}

public static StatusEffectInstance copyWithNewAmplifier(StatusEffectInstance instance, int newAmplifier) {
    return new StatusEffectInstance(
            instance.getEffectType(), instance.getDuration(), newAmplifier, instance.isAmbient(),
            instance.shouldShowParticles(), instance.shouldShowIcon());
}

public static void sendBatches(@Nullable Entity trackedEntity, @Nullable Vec3d location, List<ParticleGroup> effects, float countMultiplier, Collection<ServerPlayerEntity> trackers, boolean includeSourceEntity) {
    if (effects == null || effects.isEmpty()) {
        return;
    }
    int sourceEntityId = 0;
    var sourceType = Packets.ParticleEffects.SourceType.COORDINATE;
    if (trackedEntity != null) {
        sourceEntityId = trackedEntity.getId();
        sourceType = Packets.ParticleEffects.SourceType.ENTITY;
    }
    ArrayList<Packets.ParticleEffects.Spawn> spawns = new ArrayList<>();
    for (var effect : effects) {
        Vec3d sourceLocation = Vec3d.ZERO;
        switch (sourceType) {
            case ENTITY -> {
                sourceLocation = origin(trackedEntity, effect.batch);
            }
            case COORDINATE -> {
                if (location != null) {
                    sourceLocation = location;
                }
            }
        }
        float yaw = 0;
        float pitch = 0;
        if (trackedEntity != null) {
            yaw = trackedEntity.getYaw();
            pitch = trackedEntity.getPitch();
        }
        spawns.add(new Packets.ParticleEffects.Spawn(
                includeSourceEntity ? sourceEntityId : 0,
                yaw,
                pitch,
                sourceLocation, effect));
    }
    var packet = new Packets.ParticleEffects(sourceType, countMultiplier, spawns);
    if (trackedEntity instanceof ServerPlayerEntity serverPlayer) {
        if (Platform.util().networkS2C_CanSend(serverPlayer, Packets.ParticleEffects.ID)) {
            Platform.util().networkS2C_Send(serverPlayer, packet);
        }
    }
    trackers.forEach(serverPlayer -> {
        if (Platform.util().networkS2C_CanSend(serverPlayer, Packets.ParticleEffects.ID)) {
            Platform.util().networkS2C_Send(serverPlayer, packet);
        }
    });
}

public static EntityActionsAllowed fromEffects(Collection<RegistryEntry<StatusEffect>> effects) {
    var initial = EntityActionsAllowed.ANY;
    var limiters = effects.stream()
            .map(effect -> ((ActionImpairing)effect.value()).actionsAllowed())
            .filter(Objects::nonNull)
            .toList();
    if (limiters.size() == 0) {
        return initial;
    }
    var canJump = initial.canJump();
    var canMove = initial.canMove();
    var canAttack = initial.players().canAttack();
    var canUseItem = initial.players().canUseItem();
    var canCastSpell = initial.players().canCastSpell();
    var canUseAI = initial.mobs().canUseAI();
    var reason = initial.reason();

    for (var impairing: limiters) {
        canJump = canJump && impairing.canJump();
        canMove = canMove && impairing.canMove();
        canAttack = canAttack && impairing.players().canAttack();
        canUseItem = canUseItem && impairing.players().canUseItem();
        canCastSpell = canCastSpell && impairing.players().canCastSpell();
        canUseAI = canUseAI && impairing.mobs().canUseAI();
        reason = (impairing.reason().ordinal() > reason.ordinal()) ? impairing.reason() : reason;
    }

    return new EntityActionsAllowed(canJump, canMove,
            new PlayersAllowed(canAttack, canUseItem, canCastSpell),
            new MobsAllowed(canUseAI),
            reason);
}

