public static boolean isImpaired(LivingEntity entity, Common action) {
    var actionsAllowed = ((ControlledEntity)entity).actionImpairing();
    var allowed = true;
    switch (action) {
        case MOVE -> {
            allowed = actionsAllowed.canMove();
        }
        case JUMP -> {
            allowed = actionsAllowed.canJump();
        }
    }
    return !allowed;
}

public static boolean isImpaired(LivingEntity player, Player action, boolean showError) {
    var allowed = true;
    var actionsAllowed = ((ControlledEntity)player).actionImpairing();
    switch (action) {
        case ATTACK -> {
            allowed = actionsAllowed.players().canAttack();
        }
        case ITEM_USE -> {
            allowed = actionsAllowed.players().canUseItem();
        }
        case CAST_SPELL -> {
            allowed = actionsAllowed.players().canCastSpell();
        }
    }
    if (player.getWorld().isClient && showError && !allowed) {
        HudMessages.INSTANCE.actionImpaired(actionsAllowed.reason());
    }
    return !allowed;
}

public void castAttemptError(SpellCast.Attempt attempt) {
    if (attemptDisplayed) {
        return;
    }
    if (attempt.isSuccess() || attempt.isFail()) {
        attemptDisplayed = true;
    }
    if (!attempt.isFail() || !SpellEngineClient.config.showSpellCastErrors) { return; }
    var translationKey = castAttemptPrefix + attempt.result().toString().toLowerCase(Locale.ENGLISH);
    MutableText message = null;
    switch (attempt.result()) {
        case MISSING_ITEM -> {
            var item = attempt.missingItem().item();
            if (item != null) {
                var itemName = I18n.translate(item.getTranslationKey());
                message = Text.translatable(translationKey, itemName);
            }
        }
        case ON_COOLDOWN -> {
            message = Text.translatable(translationKey);
        }
    }
    if (message != null) {
        error(message.formatted(Formatting.RED));
    }
}

