public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    var bubble = createBubble(world, spellStats);
    bubble.setPos(rayTraceResult.getLocation().x, rayTraceResult.getLocation().y, rayTraceResult.getLocation().z);
    if (isNotFakePlayer(shooter)) {
        bubble.setOwner(shooter);
    }
    world.addFreshEntity(bubble);
    bubble.tryCapturing(rayTraceResult.getEntity());
}

public BubbleEntity createBubble(Level level, SpellStats spellStats) {
    return new BubbleEntity(level, (int) (100 + spellStats.getDurationMultiplier() * EXTEND_TIME.getAsInt()), (float) (DAMAGE.getAsDouble() + spellStats.getAmpMultiplier() * AMP_VALUE.getAsDouble() + spellStats.getDamageModifier()));
}

public boolean tryCapturing(Entity target) {
    if (!this.entityData.get(HAS_POPPED) && this.getPassengers().isEmpty() && this.canHitEntity(target)) {
        target.startRiding(this);
        return !this.getPassengers().isEmpty();
    }
    return false;
}

protected boolean canHitEntity(Entity pTarget) {
    if (pTarget != null && pTarget.getUUID() != null) {
        if (this.hasDismounted.contains(pTarget.getUUID())) {
            return false;
        }
    }
    if (pTarget instanceof Player player && player.isSleeping()) {
        return false;
    }
    return !pTarget.getType().is(EntityTags.BUBBLE_BLACKLIST) && !(pTarget.getVehicle() instanceof BubbleEntity);
}

public Vec3 getDismountLocationForPassenger(LivingEntity passenger) {
    if (passenger != null && passenger.getUUID() != null) {
        this.hasDismounted.add(passenger.getUUID());
    }
    return super.getDismountLocationForPassenger(passenger);
}

