public static void onFlyWallDamage(LivingDamageEvent.Pre event) {
    var container = event.getContainer();
    var source = container.getSource();
    LivingEntity entity = event.getEntity();
    if (entity == null || !entity.hasEffect(ModPotions.BOUNCE_EFFECT)) {
        return;
    }
    boolean isPlayer = entity instanceof Player;
    if (!isPlayer) {
        return;
    }
    if (source.is(DamageTypes.FLY_INTO_WALL)) {
        container.setNewDamage(0);
        Vec3 lookAngle = entity.getLookAngle();

        entity.setDeltaMovement(lookAngle.scale(-2));
        entity.hurtMarked = true;
    }
}

public static void totemEvent(final LivingDeathEvent event) {
    LivingEntity entity = event.getEntity();
    if (!(entity instanceof Player player))
        return;
    var holder = PerkUtil.getHolderForPerk(TotemPerk.INSTANCE, entity);
    if (holder == null)
        return;
    CompoundTag tag = holder.getB().getTagForPerk(TotemPerk.INSTANCE);
    if (tag == null || !tag.getBoolean("isActive")) {
        return;
    }
    entity.setHealth(1.0F);
    entity.removeAllEffects();
    entity.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 900, 1));
    entity.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
    entity.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
    entity.level.broadcastEntityEvent(entity, (byte) 35);
    tag.putBoolean("isActive", false);
    holder.getA().set(DataComponentRegistry.ARMOR_PERKS, holder.getB().setTagForPerk(TotemPerk.INSTANCE, tag));
    PortUtil.sendMessage(entity, Component.translatable("ars_nouveau.totem_perk.trigger"));
    event.setCanceled(true);
}

public static void sleepEvent(final SleepFinishedTimeEvent event) {
    for (Player p : event.getLevel().players()) {
        var holder = PerkUtil.getHolderForPerk(TotemPerk.INSTANCE, p);
        if (holder == null)
            continue;
        CompoundTag tag = holder.getB().getTagForPerk(TotemPerk.INSTANCE);
        if (tag != null) {
            tag.putBoolean("isActive", true);
            holder.getA().set(DataComponentRegistry.ARMOR_PERKS, holder.getB().setTagForPerk(TotemPerk.INSTANCE, tag));
        }
        PortUtil.sendMessage(p, Component.translatable("ars_nouveau.totem_perk.active"));
    }
}

public static @Nullable Pair<ItemStack, ArmorPerkHolder> getHolderForPerk(IPerk perk, LivingEntity entity) {
    ArmorPerkHolder highestHolder = null;
    ItemStack selectedStack = null;
    int maxCount = 0;
    for (ItemStack stack : entity.getArmorSlots()) {
        var data = stack.get(DataComponentRegistry.ARMOR_PERKS);
        if (data == null) {
            continue;
        }
        for (PerkInstance instance : data.getPerkInstances(stack)) {
            if (instance.getPerk() == perk) {
                maxCount = Math.max(maxCount, instance.getSlot().value());
                highestHolder = data;
                selectedStack = stack;
            }
        }
    }
    if (highestHolder == null) {
        return null;
    }
    return new Pair<>(selectedStack, highestHolder);
}

